/***********************************************************************************************************************
 * Builds and shows the first admin screen. ui_admin_init() is not used: it would re-init the theme, and every admin
 * screen is Temporary, so it is created here and deleted by SquareLine's unload callback once another screen shows.
 **********************************************************************************************************************/
void ui_service_admin_open(void)
{
    _ui_screen_change(&ui_AdminLogin, LV_SCR_LOAD_ANIM_NONE, 0, 0, &ui_AdminLogin_screen_init);
}
